async (page) => {
const checks=[],errors=[];page.on('pageerror',e=>errors.push(e.message));const check=(v,s)=>{if(!v)throw Error(s);checks.push(s);};
await page.setViewportSize({width:1440,height:1000});await page.goto('http://127.0.0.1:5173/fiche-creation.html');await page.evaluate(()=>localStorage.removeItem('vysora-cite-ciel-mer'));await page.reload();await page.screenshot({path:'prototype/preview/fiche-desktop.png'});
await page.context().grantPermissions(['clipboard-read','clipboard-write']);await page.locator('[data-copy]').first().click();check((await page.evaluate(()=>navigator.clipboard.readText())).includes('tours élancées'),'Copie du prompt');
await page.locator('#save').click();await page.locator('#useful').click();check(await page.locator('#useful-count').textContent()==='390','Vote Utile');await page.reload();check(await page.locator('#save').getAttribute('aria-pressed')==='true','Enregistrement persistant');await page.locator('#save').click();await page.locator('#useful').click();
await page.locator('.image-open').click();check(await page.locator('#lightbox').evaluate(d=>d.open),'Image agrandie');await page.keyboard.press('Escape');check(await page.locator('.image-open').evaluate(e=>e===document.activeElement),'Focus restitué');
await page.locator('[data-try]').first().click();await page.locator('input[value="Réussi"]').check();await page.locator('#try-note').fill('Les tours sont bien centrées.');await page.locator('#try-form button').click();check(await page.locator('[data-repro-count]').first().textContent()==='45','Reproduction et compteur');check((await page.locator('.compatibility tbody tr').first().textContent()).includes('31'),'Tableau actualisé');
await page.locator('[data-reply]').first().click();await page.locator('#comment').fill('Merci pour cette précision.');await page.locator('#comment-form .btn-primary').click();check(await page.locator('#comment-count').textContent()==='3','Commentaire ajouté');check((await page.locator('.comment-row').last().textContent()).includes('En réponse à Aïssatou'),'Réponse contextualisée');
await page.locator('#tweaks-open').click();for(const [name,value]of Object.entries({accent:'deep',density:'compact',layout:'immersive',effects:'strong',motion:'none'})){await page.locator(`[name="${name}"]`).selectOption(value);check(await page.locator('body').getAttribute('data-'+name)===value,'Tweaks '+name);}await page.locator('#tweaks-form button').click();await page.waitForTimeout(80);check(await page.locator('body').getAttribute('data-layout')==='balanced','Réinitialisation');await page.keyboard.press('Escape');
await page.evaluate(()=>localStorage.removeItem('vysora-cite-ciel-mer'));await page.reload();
for(const width of [1440,1024,768,390,375,320]){await page.setViewportSize({width,height:900});await page.evaluate(()=>scrollTo(0,0));await page.waitForTimeout(150);check(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'Sans débordement '+width);if(width===390){await page.screenshot({path:'prototype/preview/fiche-mobile.png'});await page.locator('.menu-toggle').click();check(await page.locator('#mobile-panel').isVisible(),'Navigation mobile');await page.keyboard.press('Escape');}if(width===768)await page.screenshot({path:'prototype/preview/fiche-tablet.png'});}
await page.setViewportSize({width:1440,height:1000});await page.emulateMedia({reducedMotion:'reduce'});check(await page.locator('.image-open>img').evaluate(e=>getComputedStyle(e).transitionDuration)==='0s','Mouvement réduit');
for(let y=0;y<await page.evaluate(()=>document.body.scrollHeight);y+=650){await page.evaluate(y=>scrollTo(0,y),y);await page.waitForTimeout(80);}await page.locator('#parcours').scrollIntoViewIfNeeded();await page.screenshot({path:'prototype/preview/fiche-parcours.png'});await page.evaluate(()=>scrollTo(0,0));await page.screenshot({path:'prototype/preview/fiche-full.png',fullPage:true});check(await page.locator('img').evaluateAll(imgs=>imgs.every(i=>i.complete&&i.naturalWidth>0)),'Images chargées');check(errors.length===0,'Aucune erreur JavaScript');
await page.goto('http://127.0.0.1:5173/explorer.html');await page.locator('a[href="fiche-creation.html?id=cite-ciel-mer"]').first().click();await page.waitForURL('**/fiche-creation.html?id=cite-ciel-mer');check(true,'Accès depuis Explorer');return{checks,errors};
}

